# Interactive explorer for the Oʻahu electricity study (pre-v1.02).
# Runs as a serverless shinylive site; data in data/ is generated by
# build/build_explorer_data.py from the full solve fleet.

library(shiny)
library(bslib)
library(dplyr)
library(tidyr)
library(ggplot2)
library(readr)
library(jsonlite)
library(scales)
library(plotly)

scen   <- read_csv("data/scenarios.csv", show_col_types = FALSE)
gen    <- read_csv("data/generation.csv", show_col_types = FALSE)
costs  <- read_csv("data/costs.csv", show_col_types = FALSE)
hourly <- read_csv("data/dispatch_hourly.csv", show_col_types = FALSE)
meta   <- fromJSON("data/meta.json")

TECH_COLORS <- c(
  "Oil" = "#8c564b", "LNG" = "#7f7f7f", "Waste-to-energy" = "#bcbd22",
  "Geothermal (EGS)" = "#d62728", "Onshore wind" = "#1f77b4",
  "Offshore wind" = "#17becf", "Utility solar" = "#ff7f0e",
  "Distributed solar (netted)" = "#ffbb78",
  "Distributed solar (modeled)" = "#f7e08a",
  "Battery storage" = "#2ca02c", "Other" = "#c7c7c7"
)
TECH_ORDER <- names(TECH_COLORS)

HOUR_COLORS <- c(
  "Geothermal" = "#756bb1", "Waste-to-energy" = "#7f7f7f",
  "Thermal (oil/LNG)" = "#843c39", "Wind" = "#5fa2ce",
  "Utility solar" = "#f2c744", "Rooftop solar" = "#f7e08a",
  "Battery discharge (net)" = "#2ca02c",
  "Curtailed solar & wind" = "#d9d9d9"
)
# withdrawals drawn below zero (stored as negative MW in the extract); the
# demand line is retail demand only, so these account for the generation
# stack topping the line
BELOW_COLORS <- c("Hydrogen production" = "#e377c2",
                  "EV charging" = "#17becf",
                  "Battery charging (net)" = "#2ca02c")

OILS  <- c("Market 10th percentile", "Brent futures", "EIA reference",
           "Market 90th percentile")
# solar_mult is relative to the study baseline (1.2x mainland ATB), so the
# premiums over mainland costs are 20% / 80% / 104%
SOLAR_LABELS <- c("1" = "20% Hawaiʻi premium",
                  "1.5" = "80% Hawaiʻi premium",
                  "1.7" = "104% Hawaiʻi premium")
TRAJS <- unique(scen$trajectory)
CONFIG_ORDER <- scen |> distinct(config_label) |> pull(config_label)
# scenario dropdown choices: plain-English label -> scenario id
SCEN_CHOICES <- local({
  s <- scen |> arrange(short_label)
  setNames(s$scenario, s$short_label)
})
desc_of <- function(id) scen$description[scen$scenario == id][1]
short_of <- function(id) scen$short_label[scen$scenario == id][1]

# Published-plan cells constrain generation to somebody else's plan. Each plan
# is paired with the rooftop trajectory its own customer-solar assumptions
# track; shown on any other trajectory it has been RESCALED, and the footnote
# below says so wherever such a cell can appear. Without it the two variants
# look like the same plan costing different amounts.
RESCALE_NOTE <- paste(
  "<b>Rescaled plan.</b> A published plan states its generation mix for the",
  "island demand <i>it</i> assumed. To price that mix here it is converted to",
  "shares and applied to the grid demand this rooftop trajectory leaves for",
  "the utility to serve — that conversion is what \u201crescaled\u201d means.",
  "A plan shown on its own trajectory is rescaled only for the modest",
  "difference between its demand forecast and ours. A plan marked",
  "<i>rescaled to this trajectory</i> has been moved onto a different rooftop",
  "trajectory altogether, so that the two plans can be compared on common",
  "ground: the accelerated and base trajectories leave roughly 5,400 and",
  "7,200 GWh of grid demand in 2045, and a plan costs more simply by serving",
  "more. Compare a rescaled cell with the other plan on the <i>same</i>",
  "trajectory; do not compare it with the same plan on its home trajectory."
)

rescale_note <- function(ids) {
  # tolerate an older extract that predates the column, so a data/app version
  # skew degrades to "no note" rather than a broken tab
  if (is.null(scen$rescaled)) return(NULL)
  ids <- ids[!is.na(ids)]
  if (!length(ids)) return(NULL)
  if (!any(scen$rescaled[scen$scenario %in% ids] == 1)) return(NULL)
  tags$div(class = "small text-muted mt-2 border-top pt-2", HTML(RESCALE_NOTE))
}

axis_selectors <- function(id, mult = TRUE) {
  tagList(
    selectInput(paste0(id, "_traj"), "Rooftop trajectory", TRAJS,
                selected = "Conservative rooftop (base)"),
    selectInput(paste0(id, "_oil"), "Oil-price case",
                intersect(OILS, unique(scen$oil_label)),
                selected = "EIA reference"),
    if (mult) selectInput(paste0(id, "_mult"), "Utility solar cost",
                          local({
                            sm <- sort(unique(scen$solar_mult))
                            setNames(sm, SOLAR_LABELS[as.character(sm)])
                          }), selected = 1.0),
    selectInput(paste0(id, "_screen"), "Land screen",
                unique(scen$land_screen), selected = "Reference"),
    selectInput(paste0(id, "_basis"), "Solar/battery cost basis",
                unique(scen$solar_basis), selected = "ATB Moderate")
  )
}

filter_axes <- function(df, input, id, mult = TRUE) {
  out <- df |>
    filter(trajectory == input[[paste0(id, "_traj")]],
           oil_label == input[[paste0(id, "_oil")]],
           land_screen == input[[paste0(id, "_screen")]],
           solar_basis == input[[paste0(id, "_basis")]])
  if (mult) out <- filter(out, solar_mult == input[[paste0(id, "_mult")]])
  out
}

