           plotOutput("hr_plot", height = 460))
    )
  ),

  nav_panel("All solves",
    layout_sidebar(
      sidebar = sidebar(
        checkboxGroupInput("a_oil", "Oil cases",
                           intersect(OILS, unique(scen$oil_label)),
